// Generated by `npm run import:cwt` from cwtools-stellaris-config, then maintained by hand.
// Re-running the importer proposes a diff; it never overwrites hand edits automatically.

import { DefinitionTypeId } from "../catalog.js";

import { defineType, effectEntries, item, keyedBlocks, literal, occurs } from "../ir.js";

import type { DefinitionType } from "../ir.js";

export const scriptedEffect: DefinitionType = defineType({
  id: DefinitionTypeId.ScriptedEffect,
  // Every key at the root of a file here is a scripted effect. The ported
  // corpus left 89 of them out of the type and declared each as a command of
  // its own instead; the game's own documentation lists none of those names,
  // and `common/scripted_effects` defines every one of the 84 the base game
  // still has.
  source: keyedBlocks("common/scripted_effects"),
  variants: [],
  localisation: [],
  modifiers: [],
  entries: [item(literal("optimize_memory"), occurs.any), effectEntries()],
});
